function isStringArray(v: any): v is string[] {
  return Array.isArray(v) && v.every(e => typeof e === 'string');
}

function concatIfArray(v: any): string {
  if (isStringArray(v)) {
    // v is now string[]
    return v.join('');
  }
  return '';
}

// Example
console.log(concatIfArray(['a','b','c'])); // abc
console.log(concatIfArray([1,2,3])); // ''

function mockNum(id: number): Promise<number> {
  return new Promise(res => setTimeout(() => res(id), id * 50));
}

async function productThree(): Promise<number> {
  const vals = await Promise.all([mockNum(1), mockNum(2), mockNum(3)]);
  return vals.reduce((a,b) => a*b, 1);
}

productThree().then(p => console.log('Product =', p)); // after 150ms prints 6

Mixing async/await and .then can lead to confusing execution order because .then callbacks are always scheduled as microtasks after the current call stack, while await pauses the async function until the awaited promise settles. If a .then is attached to a promise that is also awaited, the .then may run before code after the await, breaking the intended sequence. Example:

async function mixed() {
  const p = Promise.resolve(1);
  p.then(v => console.log('then', v)); // scheduled immediately
  const x = await p; // waits for same promise, but after then runs
  console.log('await', x);
}

mixed(); // output: then 1 \n await 1

The console shows "then" before "await", which may be surprising. Keeping to one style per function avoids such ordering surprises.

Define the union:

type JsonConfig = {host:string; port:number};
type YamlConfig = {endpoint:string; timeout:number};

type ConfigResult =
  | {type:'json'; data: JsonConfig}
  | {type:'yaml'; data: YamlConfig};

Implement a type guard:

function isJsonResult(r: ConfigResult): r is {type:'json'; data: JsonConfig} {
  return r.type === 'json';
}

The loadConfig function reads the file, checks the extension, parses accordingly, and returns the appropriate object. Callers can write:

const cfg = loadConfig('app.yaml');
if (isJsonResult(cfg)) {
  // cfg.data is JsonConfig, safe to access host, port
} else {
  // cfg.data is YamlConfig, safe to access endpoint, timeout
}

Using the discriminated union ensures exhaustive checking: if a new type is added, the compiler will warn about missing branches in the if/else chain, preserving type safety.

class TimeoutError extends Error { constructor(msg='Timeout') { super(msg); this.name='TimeoutError'; } }

function fetchWithTimeout(url: string, ms: number): Promise<Response> {
  const timeout = new Promise<never>((_, reject) =>
    setTimeout(() => reject(new TimeoutError()), ms)
  );
  return Promise.race([fetch(url), timeout]);
}

// usage
fetchWithTimeout('https://example.com', 2000)
  .then(r => console.log('Got', r.status))
  .catch(e => console.error(e instanceof TimeoutError ? 'Timed out' : e));
